import fs from 'node:fs';
const path='hu/index.html';
let s=fs.readFileSync(path,'utf8');
const from='<strong>Négy fő szolgáltatás:</strong> portréfotózás, brandfotózás, felsővezetői eseményfotózás és művészi fotográfia.';
const to='<strong>Négy fő szolgáltatás:</strong> vezetői portréfotózás, brandfotózás, felsővezetői eseményfotózás és művészi fotográfia.';
const count=s.split(from).length-1;
if(count!==1) throw new Error(`Expected one HU principal-service sentence, found ${count}`);
s=s.replace(from,to);
fs.writeFileSync(path,s);
console.log('Restored vezetői portréfotózás as the Hungarian principal service.');
